import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"一键安装","description":"Linux 脚本用 apt 或 yum/dnf 安装 PostgreSQL，并询问是否安装 Redis。不下载 KiriVers 二进制。","frontmatter":{"title":"一键安装","description":"Linux 脚本用 apt 或 yum/dnf 安装 PostgreSQL，并询问是否安装 Redis。不下载 KiriVers 二进制。"},"headers":[],"relativePath":"guide/install/one-click.md","filePath":"guide/install/one-click.md","lastUpdated":1790057721000}`),a={name:`guide/install/one-click.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="一键安装" tabindex="-1">一键安装 <a class="header-anchor" href="#一键安装" aria-label="Permalink to “一键安装”">​</a></h1><p>仓库脚本 <a href="https://github.com/Kirizu-Official/KiriVers/blob/main/scripts/install-deps.sh" target="_blank" rel="noreferrer"><code>scripts/install-deps.sh</code></a> 只在 Linux 上用 <strong>apt 或 yum/dnf</strong> 安装 PostgreSQL，并询问是否同样用系统包装 <strong>Redis</strong>。</p><h2 id="做什么、不做什么" tabindex="-1">做什么、不做什么 <a class="header-anchor" href="#做什么、不做什么" aria-label="Permalink to “做什么、不做什么”">​</a></h2><table tabindex="0"><thead><tr><th>做</th><th>不做</th></tr></thead><tbody><tr><td>以 root/sudo 安装 PostgreSQL 并尝试启用服务</td><td>下载 KiriVers 安装包</td></tr><tr><td>询问后可选安装 Redis</td><td>调用 Docker</td></tr><tr><td>打印下一步：打开手动安装页，去 GitHub Releases 取对应平台的包（<code>KiriVers-&lt;OS&gt;-&lt;Arch&gt;-&lt;sha6&gt;.zip</code>）</td><td>支持 Windows</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Windows</p><p>不要在 Windows 上运行此脚本。请使用 <a href="/guide/install/manual">手动安装</a>。</p></div><h2 id="redis-怎么选" tabindex="-1">Redis 怎么选 <a class="header-anchor" href="#redis-怎么选" aria-label="Permalink to “Redis 怎么选”">​</a></h2><ul><li><strong>可以不装</strong>：单节点、流量不大。保持 <code>cache.driver=memory</code>（默认）。</li><li><strong>应当装</strong>：多个 KiriVers 进程，或要求缓存走 Redis。<code>cache.driver=redis</code> 时<strong>启动</strong>必须 Ping 成功，否则进程不监听。运行中 Redis 断开后回退进程内内存并按间隔重连，<strong>不会</strong>在运行中一断 Redis 就立刻退出。细节见 <a href="/guide/config/cache">缓存与 Redis</a>。</li></ul><h2 id="适用系统" tabindex="-1">适用系统 <a class="header-anchor" href="#适用系统" aria-label="Permalink to “适用系统”">​</a></h2><p>能检测到 <code>apt-get</code> 或 <code>yum</code>/<code>dnf</code> 的 Linux，且需要管理员权限。macOS 与没有上述包管理器的发行版：脚本退出码 1，改用手动安装或 Docker。</p><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to “步骤”">​</a></h2><ol><li>以 root 运行（把仓库 URL 换成你实际克隆或下载脚本的位置）：</li></ol><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-83" id="tab-84" checked><label data-title="curl" for="tab-84">curl</label><input type="radio" name="group-83" id="tab-85"><label data-title="wget" for="tab-85">wget</label><input type="radio" name="group-83" id="tab-86"><label data-title="local" for="tab-86">local</label></div><div class="blocks"><div class="language-bash active line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/Kirizu-Official/KiriVers/main/scripts/install-deps.sh</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -qO-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/Kirizu-Official/KiriVers/main/scripts/install-deps.sh</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/install-deps.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></div></div><ol start="2"><li>如提示，输入本机 sudo 密码。</li><li>脚本询问是否安装 Redis：<code>y</code> 安装，回车跳过。</li><li>成功时 stdout 会提示 PostgreSQL 已安装，并指向手动安装页从 Releases 取 KiriVers 安装包。记下发行版默认的数据库端口（通常 <code>5432</code>）与系统 postgres 用户策略。</li></ol><details class="details custom-block"><summary>成功后 stdout 会写什么</summary><p>脚本打印 PostgreSQL 已安装，并指向 GitHub Releases 取包，再按手动安装页复制三份 YAML、创建管理员并启动进程。若安装了 Redis，会说明单进程可继续用 <code>cache.driver=memory</code>；多进程或 <code>cache.driver=redis</code> 时启动必须 Ping 成功。</p></details><div class="tip custom-block"><p class="custom-block-title">Releases 里下的是 zip</p><p>脚本只装数据库，不碰 KiriVers。真正取包时按<strong>前缀</strong>在 Release 页挑 <code>KiriVers-&lt;OS&gt;-&lt;Arch&gt;-&lt;sha6&gt;.zip</code>（末尾六位数是包内二进制的 SHA-256 前缀，每次发版都会变），解压得到的可执行文件才叫 <code>kirivers-&lt;os&gt;-&lt;arch&gt;</code>（Windows 为 <code>.exe</code>）。详见 <a href="/guide/install/manual">手动安装</a>。</p></div><h2 id="失败" tabindex="-1">失败 <a class="header-anchor" href="#失败" aria-label="Permalink to “失败”">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>不是 root</td><td><code>sudo</code> 重试</td></tr><tr><td>找不到 apt/yum/dnf</td><td>退出码 1；改手动或 Docker。Docker 未安装<strong>不是</strong>本脚本的失败原因</td></tr><tr><td><code>5432</code> 已被占用</td><td>停掉旧 PostgreSQL 或改 DSN 端口</td></tr><tr><td>发行版仓库没有 postgresql 包</td><td>启用发行版模块流 / 官方 PostgreSQL 仓库后再跑，或改手动安装</td></tr></tbody></table><p>下一步：<a href="/guide/install/manual">手动安装</a>。</p>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};